//! SCAN.POLY.SURF.PREP acceptance tests. Clouds and expected vertex sets are in
//! `fixtures/scan/poly/`, written by the independent Python reference
//! `fixtures/scan/poly/make_prep_fixtures.py`; nothing here was generated by running this
//! crate. Sources, cells and statuses are compared exactly, unmoved positions bit for bit
//! and smoothed positions within 1e-12 m (the reference fits the plane in exact and
//! 80-digit decimal arithmetic, the crate in f64 with the fid-num Jacobi eigensolver).
//! The small clouds at the end are hand-labelled from the spec's rules.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_geo_types::{AttributeSet, FrameRef, PointBuffer, PointCloud};
use fid_scan_poly::{prepare, PolyError, PrepParams, VertexSet, VertexStatus};

const POS_TOL: f64 = 1e-12;

fn read(name: &str) -> String {
    std::fs::read_to_string(format!("{}/fixtures/scan/poly/{name}", fid_testkit::WORKSPACE_ROOT)).unwrap()
}

struct Cloud {
    cloud: PointCloud,
    valid: Vec<bool>,
}

fn build(points: &[[f64; 3]], normals: &[[f64; 3]], valid: Vec<bool>) -> Cloud {
    let attrs = AttributeSet {
        normal: Some([
            normals.iter().map(|n| n[0]).collect(),
            normals.iter().map(|n| n[1]).collect(),
            normals.iter().map(|n| n[2]).collect(),
        ]),
        ..AttributeSet::default()
    };
    let cloud = PointCloud::new(FrameRef::from_bytes([7; 16]), PointBuffer::from_points(points), attrs).unwrap();
    Cloud { cloud, valid }
}

fn f(s: &str) -> f64 {
    s.parse().unwrap()
}

fn load_cloud(name: &str) -> Cloud {
    let text = read(&format!("{name}.txt"));
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    assert_eq!(lines.next().unwrap(), format!("cloud {name}"));
    let k: usize = lines.next().unwrap().strip_prefix("normals ").unwrap().parse().unwrap();
    let table: Vec<[f64; 3]> = (0..k)
        .map(|_| {
            let v: Vec<f64> = lines.next().unwrap().split_whitespace().map(f).collect();
            [v[0], v[1], v[2]]
        })
        .collect();
    let m: usize = lines.next().unwrap().strip_prefix("points ").unwrap().parse().unwrap();
    let (mut pts, mut nrm, mut valid) = (Vec::new(), Vec::new(), Vec::new());
    for _ in 0..m {
        let t: Vec<&str> = lines.next().unwrap().split_whitespace().collect();
        pts.push([f(t[0]), f(t[1]), f(t[2])]);
        nrm.push(table[t[3].parse::<usize>().unwrap()]);
        valid.push(t[4] == "1");
    }
    assert!(lines.next().is_none());
    build(&pts, &nrm, valid)
}

struct Row {
    source: u64,
    cell: [u32; 3],
    status: String,
    position: [f64; 3],
    near_edge: Option<bool>,
}

struct Case {
    cloud: String,
    params: PrepParams,
    rows: Vec<Row>,
}

fn load_case(case: &str) -> Case {
    let text = read(&format!("{case}.prep.txt"));
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    let mut field = |key: &str| lines.next().unwrap().strip_prefix(&format!("{key} ")).unwrap().to_string();
    assert_eq!(field("case"), case);
    let cloud = field("cloud");
    let mut params = PrepParams::new(f(&field("h")));
    params.smoothing = field("smoothing") == "1";
    params.sharp_edges = field("sharp_edges") == "1";
    params.edge_angle_rad = f(&field("edge_angle_rad"));
    let n: usize = field("vertices").parse().unwrap();
    let rows: Vec<Row> = lines
        .map(|l| {
            let t: Vec<&str> = l.split_whitespace().collect();
            Row {
                source: t[0].parse().unwrap(),
                cell: [t[1].parse().unwrap(), t[2].parse().unwrap(), t[3].parse().unwrap()],
                status: t[4].to_string(),
                position: [f(t[5]), f(t[6]), f(t[7])],
                near_edge: match t[8] {
                    "-" => None,
                    v => Some(v == "1"),
                },
            }
        })
        .collect();
    assert_eq!(rows.len(), n);
    Case { cloud, params, rows }
}

fn point(c: &Cloud, i: u64) -> [f64; 3] {
    c.cloud.point(i).unwrap()
}

fn bits(p: [f64; 3]) -> [u64; 3] {
    [p[0].to_bits(), p[1].to_bits(), p[2].to_bits()]
}

fn dist(a: [f64; 3], b: [f64; 3]) -> f64 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

/// Runs a case and checks it against the reference; returns the cloud and the result.
fn run_case(case: &str, threads: usize) -> (Cloud, Case, VertexSet) {
    let expected = load_case(case);
    let cloud = load_cloud(&expected.cloud);
    let mut params = expected.params;
    params.threads = threads;
    let got = prepare(&cloud.cloud, &cloud.valid, &params).unwrap();
    assert_eq!(got.vertices.len(), expected.rows.len(), "{case}: vertex count");
    let half = params.h * 0.5;
    let mut max_d = 0.0f64;
    for (v, row) in got.vertices.iter().zip(&expected.rows) {
        assert_eq!(v.source, row.source, "{case}: source");
        assert_eq!(v.cell, row.cell, "{case}: cell of source {}", row.source);
        assert_eq!(v.status.as_str(), row.status, "{case}: status of source {}", row.source);
        let src = point(&cloud, v.source);
        assert!(cloud.valid[v.source as usize], "{case}: invalid source {}", v.source);
        if v.status.moved() {
            for a in 0..3 {
                assert!(
                    (v.position[a] - row.position[a]).abs() <= POS_TOL,
                    "{case}: source {} axis {a}: {} vs {}",
                    v.source,
                    v.position[a],
                    row.position[a]
                );
            }
            assert!(v.displacement_m <= half, "{case}: displacement above h/2");
            assert!((v.displacement_m - dist(v.position, src)).abs() <= 1e-15);
        } else {
            assert_eq!(bits(v.position), bits(src), "{case}: kept vertex moved");
            assert_eq!(bits(v.position), bits(row.position));
            assert_eq!(v.displacement_m, 0.0);
        }
        assert!(dist(v.position, src) <= half, "REQ-003: within h/2 of its source");
        max_d = max_d.max(v.displacement_m);
    }
    assert_eq!(got.max_displacement_m, max_d);
    (cloud, expected, got)
}

/// The RMS distance to the fixtures' true plane z = 0.25 x - 0.15 y + 0.0075.
fn rms_to_plane(points: impl Iterator<Item = [f64; 3]>) -> f64 {
    let ln = (0.25f64 * 0.25 + 0.15 * 0.15 + 1.0).sqrt();
    let (mut s, mut n) = (0.0, 0.0);
    for p in points {
        let e = (0.25 * p[0] - 0.15 * p[1] - p[2] + 0.0075) / ln;
        s += e * e;
        n += 1.0;
    }
    (s / n).sqrt()
}

#[test]
fn ac1_one_unmodified_representative_per_cell() {
    let (cloud, _, got) = run_case("plane_dense_h1mm", 1);
    let mut cells: Vec<[u32; 3]> = got.vertices.iter().map(|v| v.cell).collect();
    let n = cells.len();
    cells.sort();
    cells.dedup();
    assert_eq!(cells.len(), n, "one representative per cell");
    // Every cell that holds a valid point has a representative.
    let o = cloud.cloud.aabb().unwrap().min();
    let mut occupied: Vec<[u32; 3]> = (0..cloud.cloud.len())
        .filter(|&i| cloud.valid[i as usize])
        .map(|i| {
            let p = point(&cloud, i);
            [0, 1, 2].map(|a| ((p[a] - o[a]) / 1e-3).floor() as u32)
        })
        .collect();
    occupied.sort();
    occupied.dedup();
    assert_eq!(occupied, cells);
    assert!(got.vertices.iter().all(|v| v.status == VertexStatus::Unmoved));
    assert_eq!(got.max_displacement_m, 0.0);
}

#[test]
fn ac2_smoothing_halves_the_rms_to_the_true_plane() {
    for case in ["plane_noisy_smooth", "plane_noisy_smooth_sharp"] {
        let (cloud, _, got) = run_case(case, 1);
        let before = rms_to_plane(got.vertices.iter().map(|v| point(&cloud, v.source)));
        let after = rms_to_plane(got.vertices.iter().map(|v| v.position));
        assert!(after <= 0.5 * before, "{case}: rms {before} -> {after}");
        assert!(got.vertices.iter().all(|v| v.status == VertexStatus::Smoothed));
        assert!(got.max_displacement_m <= 0.5e-3);
    }
}

#[test]
fn ac3_vertices_near_cube_edges_stay_put() {
    let (cloud, expected, got) = run_case("cube_edges_smooth_sharp", 1);
    let mut near = 0;
    let mut moved = 0;
    for (v, row) in got.vertices.iter().zip(&expected.rows) {
        if row.near_edge == Some(true) {
            near += 1;
            assert_eq!(v.status, VertexStatus::KeptEdge);
            assert_eq!(bits(v.position), bits(point(&cloud, v.source)));
        }
        if v.status.moved() {
            moved += 1;
        }
    }
    assert!(near > 0 && moved > 0, "the case exercises both sides: {near} near, {moved} moved");

    // Without sharp-edge preservation the same vertices are smoothed.
    let mut params = expected.params;
    params.sharp_edges = false;
    let off = prepare(&cloud.cloud, &cloud.valid, &params).unwrap();
    let near_moved =
        off.vertices.iter().zip(&expected.rows).filter(|(v, r)| r.near_edge == Some(true) && v.status.moved());
    assert!(near_moved.count() > 0);
}

fn same(a: &VertexSet, b: &VertexSet) {
    assert_eq!(a.vertices.len(), b.vertices.len());
    for (x, y) in a.vertices.iter().zip(&b.vertices) {
        assert_eq!((x.source, x.cell, x.status), (y.source, y.cell, y.status));
        assert_eq!(bits(x.position), bits(y.position));
        assert_eq!(x.displacement_m.to_bits(), y.displacement_m.to_bits());
    }
    assert_eq!(a.max_displacement_m.to_bits(), b.max_displacement_m.to_bits());
}

#[test]
fn ac4_thread_count_does_not_change_the_output() {
    for case in ["plane_dense_h1mm", "plane_noisy_smooth", "plane_noisy_smooth_sharp", "cube_edges_smooth_sharp"] {
        let (_, _, one) = run_case(case, 1);
        for threads in [2, 3, 16, 256] {
            let (_, _, many) = run_case(case, threads);
            same(&one, &many);
        }
    }
}

// ------------------------------------------------------------------ hand-labelled cases

fn up(n: usize) -> Vec<[f64; 3]> {
    vec![[0.0, 0.0, 1.0]; n]
}

#[test]
fn clamp_limits_a_far_move_to_half_a_cell() {
    // A flat 21 x 21 grid at 0.1 on z = 0 and one valid point 1.5 above it, alone in its
    // cell (h = 1). Its plane is nearly z = 0, so the unclamped move would be ~1.5.
    let mut pts = Vec::new();
    for i in 0..21 {
        for j in 0..21 {
            pts.push([i as f64 * 0.1, j as f64 * 0.1, 0.0]);
        }
    }
    let outlier = pts.len() as u64;
    pts.push([1.05, 1.05, 1.5]);
    let c = build(&pts, &up(pts.len()), vec![true; pts.len()]);
    let mut params = PrepParams::new(1.0);
    params.smoothing = true;
    let got = prepare(&c.cloud, &c.valid, &params).unwrap();
    let v = got.vertices.iter().find(|v| v.source == outlier).unwrap();
    assert_eq!(v.status, VertexStatus::Clamped);
    assert_eq!(v.cell, [1, 1, 1]);
    assert!(v.displacement_m <= 0.5 && v.displacement_m > 0.5 - 1e-9, "{}", v.displacement_m);
    assert!((v.position[2] - 1.0).abs() < 1e-2, "moved down towards the plane: {:?}", v.position);
    assert_eq!(got.max_displacement_m, v.displacement_m);
}

#[test]
fn collinear_and_isolated_points_are_kept() {
    // 30 points on a line: every neighbourhood has rank 1.
    let line: Vec<[f64; 3]> = (0..30).map(|i| [i as f64 * 0.1, 0.0, 0.0]).collect();
    let c = build(&line, &up(30), vec![true; 30]);
    let mut params = PrepParams::new(1.0);
    params.smoothing = true;
    let got = prepare(&c.cloud, &c.valid, &params).unwrap();
    assert_eq!(got.vertices.len(), 3);
    assert!(got.vertices.iter().all(|v| v.status == VertexStatus::KeptDegenerate));

    // Two points 10 apart (h = 1) and a third, invalid, in a cell of its own.
    let pts = [[0.0, 0.0, 0.0], [10.0, 0.0, 0.0], [5.0, 5.0, 5.0]];
    let c = build(&pts, &up(3), vec![true, true, false]);
    let got = prepare(&c.cloud, &c.valid, &params).unwrap();
    let src: Vec<u64> = got.vertices.iter().map(|v| v.source).collect();
    assert_eq!(src, [0, 1], "the cell with only an invalid point has no vertex");
    assert!(got.vertices.iter().all(|v| v.status == VertexStatus::KeptFewNeighbours));
}

#[test]
fn selection_takes_the_valid_point_nearest_the_valid_centroid() {
    // One cell (h = 1). Valid x = 0.1, 0.5, 0.6 give the centroid 0.4; point 2 sits on it
    // but is invalid, so point 1 (0.1 away) wins over point 3 (0.2) and point 0 (0.3).
    let pts = [[0.1, 0.0, 0.0], [0.5, 0.0, 0.0], [0.4, 0.0, 0.0], [0.6, 0.0, 0.0]];
    let c = build(&pts, &up(4), vec![true, true, false, true]);
    let got = prepare(&c.cloud, &c.valid, &PrepParams::new(1.0)).unwrap();
    assert_eq!(got.vertices.len(), 1);
    assert_eq!(got.vertices[0].source, 1);

    // Ties go to the lowest index: x = 0.25 and 0.75 around the centroid 0.5.
    let pts = [[0.75, 0.0, 0.0], [0.25, 0.0, 0.0]];
    let c = build(&pts, &up(2), vec![true, true]);
    let got = prepare(&c.cloud, &c.valid, &PrepParams::new(1.0)).unwrap();
    assert_eq!(got.vertices[0].source, 0);
}

#[test]
fn cells_come_in_morton_order() {
    // One point per cell at (1, 0, 0), (0, 1, 0), (0, 0, 1), (0, 0, 0) and (2, 0, 0), h = 1
    // (each half a cell in): Morton keys 1, 2, 4, 0, 8.
    let pts = [[1.5, 0.5, 0.5], [0.5, 1.5, 0.5], [0.5, 0.5, 1.5], [0.5, 0.5, 0.5], [2.5, 0.5, 0.5]];
    let c = build(&pts, &up(5), vec![true; 5]);
    let got = prepare(&c.cloud, &c.valid, &PrepParams::new(1.0)).unwrap();
    let src: Vec<u64> = got.vertices.iter().map(|v| v.source).collect();
    assert_eq!(src, [3, 0, 1, 2, 4]);
}

#[test]
fn no_valid_point_gives_an_empty_set() {
    let c = build(&[[0.0, 0.0, 0.0]], &up(1), vec![false]);
    let got = prepare(&c.cloud, &c.valid, &PrepParams::new(1.0)).unwrap();
    assert!(got.vertices.is_empty());
    assert_eq!(got.max_displacement_m, 0.0);
}

fn refused(c: &Cloud, valid: &[bool], p: PrepParams) -> &'static str {
    match prepare(&c.cloud, valid, &p) {
        Err(PolyError::InvalidParameter { name, .. }) => name,
        other => panic!("expected invalid_parameter, got {other:?}"),
    }
}

#[test]
fn bad_parameters_are_refused() {
    let c = build(&[[0.0, 0.0, 0.0], [1e-2, 0.0, 0.0]], &up(2), vec![true, true]);
    for h in [0.0, -0.0, -1.0, f64::NAN, f64::INFINITY, 2f64.powi(401)] {
        assert_eq!(refused(&c, &c.valid, PrepParams::new(h)), "h");
    }
    // A resolution too fine for the extent: 1e-2 / 1e-15 cells.
    assert_eq!(refused(&c, &c.valid, PrepParams::new(1e-15)), "h");
    for a in [0.0, -0.1, 3.5, f64::NAN] {
        let mut p = PrepParams::new(1.0);
        p.edge_angle_rad = a;
        assert_eq!(refused(&c, &c.valid, p), "edge_angle_rad");
    }
    for t in [0, 257] {
        let mut p = PrepParams::new(1.0);
        p.threads = t;
        assert_eq!(refused(&c, &c.valid, p), "threads");
    }
    assert_eq!(refused(&c, &[true], PrepParams::new(1.0)), "valid");
    let bare = PointCloud::from_points(FrameRef::from_bytes([1; 16]), &[[0.0, 0.0, 0.0]]).unwrap();
    let err = prepare(&bare, &[true], &PrepParams::new(1.0)).unwrap_err();
    assert_eq!(err, PolyError::InvalidParameter { name: "cloud.normal", reason: "the cloud has no normals" });
    assert_eq!(err.code(), "scan.poly.invalid_parameter");
}

#[test]
fn coordinates_beyond_the_index_range_fail_closed() {
    // Finite but beyond GEO.INDEX's 2^500 coordinate limit: refused when smoothing.
    let big = 2f64.powi(501);
    let c = build(&[[big, 0.0, 0.0], [big, 0.5, 0.0], [big, 0.0, 0.5]], &up(3), vec![true; 3]);
    let mut p = PrepParams::new(2f64.powi(400));
    p.smoothing = true;
    let err = prepare(&c.cloud, &c.valid, &p).unwrap_err();
    assert_eq!(err.code(), "scan.poly.index");
    // A coordinate sum that overflows is out_of_range, never a silent infinity.
    let m = f64::MAX;
    let c = build(&[[m, 0.0, 0.0], [m, 0.0, 0.0]], &up(2), vec![true, true]);
    let err = prepare(&c.cloud, &c.valid, &PrepParams::new(1.0)).unwrap_err();
    assert_eq!(err, PolyError::OutOfRange { index: 0 });
}
